import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadBambooData(){const e=readFileSync(resolve(__dirname,"../../bamboo-craft-explorer/bamboo-data.js"),"utf-8");return new Function(e+"\nreturn { BAMBOO_INFO, REGIONAL_CRAFTS, PROCESS_STEPS, GALLERY_ITEMS, SUSTAINABILITY_POINTS, REFERENCES };")()}describe("Bamboo Craft Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadBambooData()}),it("contains proper bamboo craft metadata and overview",()=>{expect(e.BAMBOO_INFO.id).toBe("bamboo-craft"),expect(e.BAMBOO_INFO.title).toContain("Bamboo"),expect(e.BAMBOO_INFO.originRegions).toContain("North-East"),expect(e.BAMBOO_INFO.history).toContain("traditional")}),it("has key regional craft and process sections",()=>{expect(Array.isArray(e.REGIONAL_CRAFTS)).toBe(!0),expect(e.REGIONAL_CRAFTS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.PROCESS_STEPS)).toBe(!0),expect(e.PROCESS_STEPS.length).toBeGreaterThanOrEqual(5)}),it("contains gallery, sustainability, and references",()=>{expect(Array.isArray(e.GALLERY_ITEMS)).toBe(!0),expect(e.GALLERY_ITEMS.length).toBeGreaterThanOrEqual(3),expect(Array.isArray(e.SUSTAINABILITY_POINTS)).toBe(!0),expect(e.SUSTAINABILITY_POINTS.length).toBeGreaterThanOrEqual(3),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})});